// https://docs.expo.dev/guides/using-eslint/
module.exports = {
  extends: 'expo',
  // `/dist` is build output, `android`/`ios` are generated by prebuild, and
  // `tools` holds a vendored third-party bundle. None of it is ours to lint,
  // and linting the vendored copy produced 9 phantom `no-undef` errors that
  // would otherwise have to be ignored one by one.
  ignorePatterns: [
    '/dist/*',
    '/android/*',
    '/ios/*',
    '/tools/*',
    '/.expo/*',
    '**/*.png',
    '**/*.jpg',
  ],
  rules: {
    // A hook below a conditional `return` registers on some renders and not
    // on others, and the only symptom is
    // "Rendered more hooks than during the previous render" on the first
    // frame after a cold start. TypeScript cannot see it and neither can a
    // device until it is too late.
    'react-hooks/rules-of-hooks': 'error',
  },
};
